#!/usr/bin/env bash
# ===========================================================================
#  Etsy Scraper - self-contained installer for macOS and Linux.
#
#  Everything is inside this one file. Run it and it will:
#    1. unpack the app into ~/etsy-scraper
#    2. install its own private copy of Node.js (no sudo, nothing system-wide)
#    3. install the app packages and the scraping browser
#    4. add an "Etsy Scraper" shortcut, and start the app
#
#  Safe to run again; anything already done is skipped. Your settings and
#  scraped files are never overwritten.
#
#    bash install-etsy-scraper.sh
# ===========================================================================
set -uo pipefail

DEST="${ETSY_SCRAPER_DIR:-$HOME/etsy-scraper}"
SELF="$0"

echo
echo "  ======================================================"
echo "    Etsy Scraper - Installer"
echo "  ======================================================"
echo
echo "  Installing to: $DEST"
echo
echo "  [1] Unpacking the app..."

case "$(uname -s)" in
  Darwin|Linux) ;;
  *) echo "  [X] This installer is for macOS and Linux. Windows has its own .cmd installer."; exit 1 ;;
esac

# macOS shipped a BSD base64 that wants -D; GNU and newer macOS take -d.
decode_b64() {
  if base64 -d </dev/null >/dev/null 2>&1; then base64 -d
  elif base64 -D </dev/null >/dev/null 2>&1; then base64 -D
  elif command -v openssl >/dev/null 2>&1; then openssl base64 -d
  else echo "  [X] No base64 decoder found (tried base64 and openssl)." >&2; return 1
  fi
}

START="$(awk '/^#PAYLOAD#$/ { print NR + 1; exit }' "$SELF")"
if [ -z "${START:-}" ]; then
  echo "  [X] This installer file looks damaged - the payload marker is missing."
  echo "      Download it again."
  exit 1
fi

mkdir -p "$DEST" || { echo "  [X] Could not create $DEST"; exit 1; }

if ! tail -n +"$START" "$SELF" | decode_b64 | tar -xzf - -C "$DEST"; then
  echo
  echo "  [X] Could not unpack the installer - the file may be incomplete."
  echo "      Download it again."
  exit 1
fi

if [ ! -f "$DEST/installer/setup.sh" ]; then
  echo "  [X] The unpacked files are incomplete. Download the installer again."
  exit 1
fi

# tar from Windows carries no executable bits; restore the ones that matter.
chmod +x "$DEST/installer/"*.sh 2>/dev/null || true
echo "      Done."

exec bash "$DEST/installer/setup.sh"

